CREATE TABLE IF NOT EXISTS public.transactions (id uuid NOT NULL DEFAULT gen_random_uuid(), buyer_id uuid NOT NULL, seller_id uuid, counterparty_email text, title text NOT NULL, description text, sector text, amount_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'MXN'::text, payment_method public.payment_method NOT NULL DEFAULT 'spei'::payment_method, commission_bps integer NOT NULL DEFAULT 250, commission_payer public.commission_payer NOT NULL DEFAULT 'split'::commission_payer, status public.transaction_status NOT NULL DEFAULT 'draft'::transaction_status, funding_deadline timestamp with time zone, delivery_deadline timestamp with time zone, funded_at timestamp with time zone, released_at timestamp with time zone, cancelled_at timestamp with time zone, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), numero text, comision_cents bigint, iva_comision_cents bigint, total_a_depositar_cents bigint, descuento_volumetrico numeric(5,4) DEFAULT 0, stripe_payment_intent_id text, clabe_virtual text, fecha_activacion timestamp with time zone, fecha_firma_pagador timestamp with time zone, fecha_firma_beneficiario timestamp with time zone, fecha_completada timestamp with time zone, fecha_cancelada timestamp with time zone, contrato_pdf_url text, auto_release_global boolean DEFAULT false, repse_requerido boolean DEFAULT false, creado_por uuid, ip_creacion inet, beneficiario_nombre text, PRIMARY KEY (id));
CREATE TABLE IF NOT EXISTS public.user_roles (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE IF NOT EXISTS public.verification_evidence (id uuid NOT NULL DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL, uploaded_by uuid NOT NULL, file_path text NOT NULL, file_name text NOT NULL, mime_type text, size_bytes integer, note text, ai_provider text, ai_model text, ai_verdict text, ai_score integer, ai_summary text, ai_raw jsonb, analyzed_at timestamp with time zone, created_at timestamp with time zone NOT NULL DEFAULT now(), latitude numeric(9,6), longitude numeric(9,6), captured_at timestamp with time zone, PRIMARY KEY (id));
